-- accounts에는 id=1, balance=1000 한 행이 있습니다.

-- Session A                       -- Session B
BEGIN;                             BEGIN;
UPDATE accounts                    -- 아래 문장은 A가 끝날 때까지 대기합니다
   SET balance = balance - 100     UPDATE accounts
 WHERE id = 1;                        SET balance = balance + 500
                                    WHERE id = 1;
COMMIT;

-- 계좌 이체 로직입니다. 하루에 몇 건씩 deadlock detected가 찍힙니다.

BEGIN;
UPDATE accounts SET balance = balance - :amt WHERE id = :from_id;
UPDATE accounts SET balance = balance + :amt WHERE id = :to_id;
COMMIT;
